function Invoke-WsmAdapterActivation($Spec,[bool]$Enable,$Ownership=$null) {
    if($Spec.Adapter -in @('FileScope','ManualWorkflow')){return}
    $d=$Spec.Desired;$desired='Disabled';if($Spec.PSObject.Properties['DesiredFinalState']){$desired=$Spec.DesiredFinalState};$active=$Enable -and $desired -in @('Enabled','Automatic','Manual','Running')
    switch($Spec.Adapter){
        WindowsFeature {if($Ownership -and $Ownership.CreatedByTool){Invoke-WsmInstallerConsumerActivation $d $Ownership.InstallerSafety $Enable}}
        ScheduledTask {if($active){Enable-ScheduledTask -TaskName $d.TaskName -TaskPath $d.TaskPath | Out-Null}else{Disable-ScheduledTask -TaskName $d.TaskName -TaskPath $d.TaskPath | Out-Null}}
        Service {if($active){$accountPolicy=Get-WsmServiceAccountPolicy $d $Spec;if($accountPolicy.Mode -ceq 'ManagedServiceAccount'){[void](Test-WsmServiceAccountTargetPreflight $accountPolicy)};Set-WsmServiceSupplement $d.Name $d.Supplement -Phase Final | Out-Null;$mode='Manual';if($desired -eq 'Automatic'){$mode='Automatic'};Set-Service -Name $d.Name -StartupType $mode;if($desired -in @('Automatic','Running')){Start-Service -Name $d.Name}}else{Set-Service -Name $d.Name -StartupType Disabled;Stop-Service -Name $d.Name -ErrorAction Stop;Set-WsmServiceSupplement $d.Name $d.Supplement -Phase Staged | Out-Null}}
        SmbShare {if($active){if(-not (Test-WsmDesiredWorldDeny $d)){Unblock-SmbShareAccess -Name $d.Name -ScopeName '*' -AccountName (Get-WsmEveryoneName) -Force | Out-Null}}else{Block-SmbShareAccess -Name $d.Name -ScopeName '*' -AccountName (Get-WsmEveryoneName) -Force | Out-Null}}
        LocalUser {if($active){Enable-LocalUser -Name $d.Name}else{Disable-LocalUser -Name $d.Name}}
        FirewallRule {if($active){Enable-NetFirewallRule -Name $d.Name}else{Disable-NetFirewallRule -Name $d.Name}}
        {$_ -in @('IISSite','IISPool')} {$m=New-WsmIisManager;try{$o=$m.Sites[$d.Name];if($Spec.Adapter -eq 'IISPool'){$o=$m.ApplicationPools[$d.Name];$o.AutoStart=$active;$xml=Read-WsmXml $d.Xml;$mode='OnDemand';if($active -and $xml.DocumentElement.HasAttribute('startMode')){$mode=$xml.DocumentElement.GetAttribute('startMode')};$o.StartMode=[Enum]::Parse([Microsoft.Web.Administration.StartMode],$mode,$true)}else{$o.ServerAutoStart=$active};$m.CommitChanges();if($active){[void]$o.Start()}elseif([string]$o.State -ne 'Stopped'){[void]$o.Stop()}}finally{$m.Dispose()}}
    }
}
function Invoke-WsmCutover {
    [CmdletBinding(SupportsShouldProcess)]param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[string]$CutoverPlanPath,[string]$CutoverPlanHash,[string]$Acknowledgement,[hashtable]$Secrets=@{},[switch]$ResumeActivation,[string]$ResumeOwner,[string]$ResumeEvidence)
    $package=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $package.Manifest.Target.Fingerprint;$plan=Read-WsmTrustedJson $CutoverPlanPath $CutoverPlanHash;Assert-WsmEnvelope $plan 'CutoverPlan';if($plan.PairId -cne $package.Manifest.PairId -or $plan.ManifestHash -ine $ExpectedHash -or $plan.TargetFingerprint -cne $package.Manifest.Target.Fingerprint -or -not $package.Manifest.Final){throw 'Cutover plan binding mismatch.'}
    if($plan.PSObject.Properties['GroupCoordination'] -and $plan.GroupCoordination){$groupDependency=Read-WsmCutoverDependencies $package $ExpectedHash $plan.DependencyEvidencePath $plan.DependencyEvidenceHash $plan.GroupCoordination.IndexPath $plan.GroupCoordination.IndexHash;if($groupDependency.GroupCoordination.GroupPlanHash -ine $plan.GroupCoordination.GroupPlanHash){throw 'Reviewed group changed after cutover preview.'}}else{Assert-WsmDependencyReceipts $package.Plan @($plan.DependencyReceipts)}
    Assert-WsmObservationHours $plan.Network.ObservationHours
    $now=[DateTime]::UtcNow;if($now -lt [DateTime]::Parse($plan.Network.MaintenanceWindowUtc).ToUniversalTime() -or $now -ge [DateTime]::Parse($plan.Network.ValidUntilUtc).ToUniversalTime()){throw 'Outside approved cutover window.'};[void](Read-WsmFreezeRecord (Join-Path $package.Root 'freeze.json') $package.Manifest.FreezeHash $package.Plan)
    if($Acknowledgement -cne ('CUTOVER '+$package.Manifest.PairId)){throw 'Cutover requires the exact pair acknowledgement shown in the reviewed plan.'}
    $paths=Get-WsmOperationPaths $StateDirectory $package.Manifest.PairId;$existing=Get-WsmOperationState $paths $package
    if($existing.Cutover -and $existing.Cutover.PlanHash -ine $CutoverPlanHash){throw 'Cannot replace a running cutover plan.'}
    if($existing.Cutover -and $existing.Cutover.NewTransactionsPossible){if($existing.Cutover.Stage -eq 'Activated'){return $existing};if(-not $ResumeActivation -or [string]::IsNullOrWhiteSpace($ResumeOwner) -or [string]::IsNullOrWhiteSpace($ResumeEvidence)){throw 'Interrupted activation requires explicit ResumeActivation, responsible owner and reconciliation evidence.'}}
    $resuming=($existing.Cutover -and $existing.Cutover.NewTransactionsPossible);if(-not $resuming){$validation=Invoke-WsmValidation $ManifestPath $ExpectedHash $StateDirectory Staged;if(-not $validation.Passed){throw 'Final-generation staging has drifted or business evidence missing.'}}
    $paths=Get-WsmOperationPaths $StateDirectory $package.Manifest.PairId
    Invoke-WsmLocked $paths.Root {$state=Get-WsmOperationState $paths $package;if(-not $PSCmdlet.ShouldProcess($state.PairId,'Apply reviewed isolated pilot identity/network and activation')){return $plan};if($state.ManifestHash -ine $ExpectedHash){throw 'Wrong applied generation.'};if($state.Cutover -and $state.Cutover.Stage -ceq 'Activated'){return $state};if($state.Cutover -and $state.Cutover.NewTransactionsPossible -and -not $resuming){throw 'Activation state changed after preview; re-open the reviewed resume flow.'};$network=$plan.Network;$before=Get-WsmNetworkSnapshot
        if(-not $state.Cutover){$state.Cutover=[pscustomobject]@{CutoverId=$plan.CutoverId;PlanHash=$CutoverPlanHash;Stage='Prepared';Before=$before;NewTransactionsPossible=$false;ObservationHours=$network.ObservationHours};Add-WsmJournal $paths $state 'CutoverPrepared' '' $state.Cutover}elseif($state.Cutover.PlanHash -ine $CutoverPlanHash){throw 'Cannot replace a running cutover plan.'}
        if($resuming){Assert-WsmActivationNetwork $network;$review=[pscustomobject]@{Owner=$ResumeOwner;Evidence=$ResumeEvidence;Utc=(Get-WsmUtc);ManifestHash=$ExpectedHash;CutoverPlanHash=$CutoverPlanHash};$state.Cutover | Add-Member NoteProperty ResumeReview $review -Force;Add-WsmJournal $paths $state 'ActivationResumeReviewed' '' $review;Invoke-WsmActivationSequence $package $paths $state -Resume;$state.Cutover.Stage='Activated';$state.Stage='PostCutoverValidationRequired';Complete-WsmCutoverObservation $paths $state;return $state};if($env:COMPUTERNAME -ine $network.FinalName){$args=@{NewName=$network.FinalName;Force=$true;ErrorAction='Stop'};if($Secrets.ContainsKey('DomainRename')){$args.DomainCredential=$Secrets.DomainRename};Rename-Computer @args | Out-Null;$state.Stage='RebootRequired';$state.Cutover.Stage='RenameRebootRequired';Add-WsmJournal $paths $state 'RenameRequiresReboot' '' ([pscustomobject]@{FinalName=$network.FinalName});return $state}
        $interface=Get-NetAdapter -Name $network.InterfaceAlias -ErrorAction Stop;if(-not $interface){throw 'Reviewed network interface absent.'}
        if(-not @(Get-NetIPAddress -InterfaceAlias $network.InterfaceAlias -IPAddress $network.FinalIP -ErrorAction SilentlyContinue).Count){$args=@{InterfaceAlias=$network.InterfaceAlias;IPAddress=$network.FinalIP;PrefixLength=$network.PrefixLength;ErrorAction='Stop'};if($network.PSObject.Properties['DefaultGateway'] -and $network.DefaultGateway){$args.DefaultGateway=$network.DefaultGateway};New-NetIPAddress @args | Out-Null}
        Set-DnsClientServerAddress -InterfaceAlias $network.InterfaceAlias -ServerAddresses $network.DnsServers
        foreach($temp in $network.TemporaryIP){if($temp -and $temp -ine $network.FinalIP){Get-NetIPAddress -InterfaceAlias $network.InterfaceAlias -IPAddress $temp -ErrorAction SilentlyContinue | Remove-NetIPAddress -Confirm:$false}}
        $final=Get-NetIPAddress -InterfaceAlias $network.InterfaceAlias -IPAddress $network.FinalIP;if([string]$final.AddressState -eq 'Duplicate'){throw 'Duplicate address detected; activation blocked.'}
        Assert-WsmActivationNetwork $network;$state.Cutover.Stage='NetworkApplied';Add-WsmJournal $paths $state 'NetworkApplied' '' ([pscustomobject]@{Interface=$network.InterfaceAlias;IP=$network.FinalIP})
        # Record the point of no automatic source restart before starting any consumer.
        $state.Cutover.NewTransactionsPossible=$true;Add-WsmJournal $paths $state 'ActivationBoundary' '' ([pscustomobject]@{ReconcileRequiredForRollback=$true})
        Invoke-WsmActivationSequence $package $paths $state
        $state.Cutover.Stage='Activated';$state.Stage='PostCutoverValidationRequired';Complete-WsmCutoverObservation $paths $state;$state
    }
}
function Get-WsmNetworkSnapshot {
    [pscustomobject]@{Name=$env:COMPUTERNAME;Addresses=@(Get-NetIPAddress | Select-Object InterfaceAlias,IPAddress,PrefixLength);DNS=@(Get-DnsClientServerAddress | Select-Object InterfaceAlias,ServerAddresses);Routes=@(Get-NetRoute | Select-Object InterfaceAlias,DestinationPrefix,NextHop)}
}
function Get-WsmAcceptanceGates {
    param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory)
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId;$s=Get-WsmOperationState $paths $p;$missing=New-Object 'System.Collections.Generic.List[string]'
    if($s.ManifestHash -ine $ExpectedHash -or -not $p.Manifest.Final){$missing.Add('Applied final generation')};if(-not $s.Cutover -or $s.Cutover.Stage -ne 'Activated'){$missing.Add('Reviewed cutover activation')}
    $v=Invoke-WsmValidation $ManifestPath $ExpectedHash $StateDirectory Final;if(-not $v.Passed){$missing.Add('Final per-item configuration and business validation')}
    foreach($check in @('DNS','Kerberos','ExternalConnectivity','Monitoring','SecurityAgent','License','UserAcceptance')){if(-not (Test-WsmEvidence $s '' $check $ExpectedHash)){$missing.Add($check)}};$accepted=$missing.Count -eq 0
    $retirement=New-Object 'System.Collections.Generic.List[string]';foreach($check in @('BackupRestore','LongCycleJobs','Observation','RetirementRetention')){if(-not (Test-WsmEvidence $s '' $check $ExpectedHash)){$retirement.Add($check)}}
    $observation=$null;try{$observation=Get-WsmObservationWindow $s}catch{$observation=[pscustomobject]@{Ready=$false;Reason=$_.Exception.Message}}
    [pscustomobject]@{Observation=$observation;PairId=$s.PairId;FinalAccepted=$accepted;RetirementReady=($accepted -and $retirement.Count -eq 0);MissingFinal=$missing.ToArray();MissingRetirement=$retirement.ToArray();Mode='IsolatedPilot';ProductionVerified=$false;RetirementAction='Report only; never deletes source or secrets'}
}
function Export-WsmStageResult {
    param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[ValidateSet('Restore','PreCutoverValidation','Cutover','PostCutoverValidation','Retirement')][string]$Stage,[string]$Path)
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $p.Manifest.Target.Fingerprint;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId
    $gates=$null;if($Stage -in @('PostCutoverValidation','Retirement')){$gates=Get-WsmAcceptanceGates $ManifestPath $ExpectedHash $StateDirectory}
    Invoke-WsmLocked $paths.Root {$s=Get-WsmOperationState $paths $p;if($s.ManifestHash -ine $ExpectedHash){$attemptMatches=($Stage -ceq 'Restore' -and $s.Stage -cin @('Failed','Cancelled','Running') -and $s.PSObject.Properties['RestoreAttempt'] -and $s.RestoreAttempt.ManifestHash -ieq $ExpectedHash -and $s.RestoreAttempt.Generation -eq $p.Manifest.Generation);if(-not $attemptMatches){throw 'No current applied generation or matching durable restore attempt.'}};$status='Blocked';switch($Stage){Restore{$status=$s.Stage;if($status -notin @('Succeeded','Failed','Cancelled','RebootRequired','ManualEvidenceRequired')){$status='Blocked'}};PreCutoverValidation{$pathV=Join-Path $paths.Root 'validation-Staged.json';if([IO.File]::Exists($pathV)){$v=Read-WsmJson $pathV;if($v.ManifestHash -ieq $ExpectedHash -and $v.Passed){$status='Succeeded'}}};Cutover{if($s.Cutover -and $s.Cutover.Stage -eq 'Activated'){$status='Succeeded'}};PostCutoverValidation{if($gates.FinalAccepted){$status='Succeeded'}else{$status='ManualEvidenceRequired'}};Retirement{if($gates.RetirementReady){$status='Succeeded'}else{$status='ManualEvidenceRequired'}}};$s.ResultSequence++;$r=[pscustomobject]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='StageResult';BatchId=$p.Manifest.BatchId;PairId=$p.Manifest.PairId;SourceHostId=$p.Plan.Source.HostId;TargetHostId=$p.Plan.Target.HostId;TargetFingerprint=$p.Plan.Target.Fingerprint;InventoryRevision=$p.Manifest.InventoryRevision;DecisionRevision=$p.Manifest.DecisionRevision;ApprovalId=$p.Manifest.ApprovalId;PlanHash=$p.Manifest.PlanHash;ManifestHash=$ExpectedHash;PayloadGeneration=$p.Manifest.Generation;RunId=$s.RunId;Sequence=$s.ResultSequence;Stage=$Stage;Status=$status;ProducedUtc=(Get-WsmUtc);Mode='IsolatedPilot';ProductionVerified=$false;JournalHash=$s.JournalHash};Write-WsmJson $Path $r;Add-WsmJournal $paths $s 'StageResultExported' '' ([pscustomobject]@{Stage=$Stage;Sequence=$r.Sequence;Status=$status});[pscustomobject]@{Path=[IO.Path]::GetFullPath($Path);SHA256=(Get-FileHash -LiteralPath $Path).Hash;Result=$r}}
}
